// src/components/Projects.js
import React, { useState } from 'react';
import './Projects.css';
import PixelCard from './PixelCard';
import { CATEGORIES, projects } from './projectsData';

const Projects = () => {
  const [activeCategory, setActiveCategory] = useState(null); // Start with null to show category selection
  const [isTransitioning, setIsTransitioning] = useState(false);

  const handleCategoryClick = (category) => {
    if (activeCategory === category) return; // Don't re-click same category
    
    setIsTransitioning(true);
    setTimeout(() => {
      setActiveCategory(category);
      setIsTransitioning(false);
    }, 300);
  };

  const goBackToCategories = () => {
    setIsTransitioning(true);
    setTimeout(() => {
      setActiveCategory(null);
      setIsTransitioning(false);
    }, 300);
  };

  const filteredProjects = activeCategory ? projects.filter(p => p.category === activeCategory) : [];

  // Category selection screen (full-screen cards)
  if (!activeCategory) {
    return (
      <div className="projects-container">
        <h1 className="projects-title">My Projects</h1>
        <div className={`category-selection-grid ${isTransitioning ? 'transitioning' : ''}`}>
          {CATEGORIES.map((category, index) => (
            <PixelCard 
              key={category} 
              variant={getCategoryVariant(index)} 
              className="category-card-fullscreen"
            >
              <div 
                className="category-content-fullscreen"
                onClick={() => handleCategoryClick(category)}
              >
                <h2 className="category-title">{category}</h2>
                <p className="category-subtitle">
                  {getCategoryDescription(category)}
                </p>
                <div className="category-count">
                  {projects.filter(p => p.category === category).length} Projects
                </div>
              </div>
            </PixelCard>
          ))}
        </div>
      </div>
    );
  }

  // Project grid screen
  return (
    <div className="projects-container">
      <div className="projects-header">
        <button className="back-button" onClick={goBackToCategories}>
          ← Back to Categories
        </button>
        <h1 className="projects-title">{activeCategory} Projects</h1>
      </div>

      <div className={`projects-grid ${isTransitioning ? 'transitioning' : ''}`}>
        {filteredProjects.map(project => (
          <PixelCard key={project.id} variant="pink" className="project-pixel-card">
            <div className="project-content">
              <img src={project.image} alt={project.title} className="proj-img" />
              <h3>{project.title}</h3>
              <p>{project.description}</p>
              <div className="project-tech">
                {project.technologies.map((tech, i) => (
                  <span key={i} className="tech-tag">{tech}</span>
                ))}
              </div>
              <a
                href={project.link}
                target="_blank"
                rel="noopener noreferrer"
                className="project-link"
              >
                View Project
              </a>
            </div>
          </PixelCard>
        ))}
      </div>
    </div>
  );
};

// Helper functions
const getCategoryVariant = (index) => {
  const variants = ['default', 'blue', 'yellow', 'pink'];
  return variants[index % variants.length];
};

const getCategoryDescription = (category) => {
  const descriptions = {
    'AI': 'Artificial Intelligence & Machine Learning projects',
    'Data': 'Data Science, Analytics & Visualization projects',
    'Hackathons': 'Competition projects and rapid prototypes',
    'Award Winning': 'Recognition-worthy and published work',
    'ReactJS': 'Web applications built with ReactJS',
    'Trivia Games': 'Fun and engaging trivia game projects',
  };
  return descriptions[category] || 'Explore my work in this category';
};

export default Projects;
