import React from 'react';
import ShinyText from './ShinyText';
import './Education.css';

const education = [
  {
    degree: "Masters in Artificial Intelligence",
    institution: "National College of Ireland, Dublin",
    period: "2024 – 2025",
    gpa: "2:1 Honors",
    highlights: ['Machine Learning', 'Computer Vision', 'Deep Learning']
  },
  {
    degree: "B.Eng. in Computer Science",
    institution: "Vidyalankar Institute of Technology",
    period: "2020 – 2024",
    gpa: "8.5 CGPA",
    highlights: ['Algorithms', 'Data Structures', 'Full-Stack']
  },
  {
    degree: "Higher Secondary (12th)",
    institution: "Maharashtra State Board",
    period: "2019 – 2020",
    gpa: "94.4%",
    highlights: ['Mathematics', 'Physics', 'Chemistry']
  },
  {
    degree: "Secondary School (10th)",
    institution: "Maharashtra State Board",
    period: "2017 – 2018",
    gpa: "95%+",
    highlights: ['Science Stream', 'Tech Passion', 'Distinction']
  }
];

export default function Education() {
  return (
    <section className="edu-section">
      <div className="edu-container">
        <div className="edu-header">
          <h1 className="edu-title">
            <ShinyText text="Education" className="shiny-text" disabled={false} speed={3} />
          </h1>
        </div>

        <div className="edu-grid">
          {education.map((edu, i) => (
            <div key={i} className={`edu-card edu-card-${i}`}>
              <div className="edu-icon">{i === 0 ? '🎓' : i === 1 ? '💻' : i === 2 ? '📚' : '⭐'}</div>
              
              <h3 className="edu-degree">{edu.degree}</h3>
              
              <div className="edu-meta-section">
                <span className="edu-institution">{edu.institution}</span>
                <span className="edu-period">{edu.period}</span>
              </div>

              <div className="edu-gpa-badge">{edu.gpa}</div>

              <div className="edu-highlights">
                {edu.highlights.map((highlight, j) => (
                  <span key={j} className="edu-highlight-tag">{highlight}</span>
                ))}
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}
