// src/components/Contact.js
import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { db } from '../Firebase'; // Ensure Firebase is initialized
import { collection, addDoc, serverTimestamp } from 'firebase/firestore';
import './Contact.css';

const Contact = () => {
  const [email, setEmail] = useState('');
  const [message, setMessage] = useState('');
  const [wordCount, setWordCount] = useState(0);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState('');
  const [submitSuccess, setSubmitSuccess] = useState(false);
  const [currentTestimonialIndex, setCurrentTestimonialIndex] = useState(0);

  const WORD_LIMIT = 300;

  // Testimonials data - Add your LOR excerpts here
  const testimonials = [
  {
    quote: "An exceptionally bright and hardworking student with a natural ability to grasp complex concepts and apply them effectively.",
    author: "Mr. Amit Nerurkar",
    role: "Assistant Professor, Computer Engineering",
    institution: "Vidyalankar Institute of Technology, Mumbai"
  },
  {
    quote: "Rajat consistently showcased innovative thinking, leadership, and technical acumen across projects in Machine Learning, Web Development, and Blockchain.",
    author: "Prof. Sachin Deshpande",
    role: "Associate Professor, Computer Engineering",
    institution: "Vidyalankar Institute of Technology, Mumbai"
  },
  {
    quote: "He demonstrates integrity, dedication, and an unyielding commitment to academic and personal growth — truly an inspiring student.",
    author: "Dr. Kavita P. Shirsat",
    role: "Associate Professor, Computer Engineering",
    institution: "Vidyalankar Institute of Technology, Mumbai"
  },
  {
    quote: "Rajat is a young man of great potential — disciplined, respectful, and deeply passionate about using Artificial Intelligence for societal benefit.",
    author: "Mr. Shamrao Pandurang Kumbhar",
    role: "Superintending Engineer",
    institution: "Public Works Department, Government of Maharashtra"
  },
  {
    quote: "His technical versatility, attention to detail, and collaborative spirit make him a valuable contributor to any impactful technology project.",
    author: "Mr. Avinash Pedgaonkar",
    role: "Senior Director (IT)",
    institution: "National Informatics Centre, Government of India"
  }
];

  useEffect(() => {
    const words = message.trim().split(/\s+/);
    setWordCount(message.trim() === '' ? 0 : words.length);
  }, [message]);

  // Auto-rotate testimonials every 6 seconds
  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentTestimonialIndex((prev) => (prev + 1) % testimonials.length);
    }, 6000);
    return () => clearInterval(interval);
  }, [testimonials.length]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSubmitError('');
    setSubmitSuccess(false);

    if (wordCount > WORD_LIMIT) {
      setSubmitError(`Message exceeds ${WORD_LIMIT} word limit`);
      return;
    }

    if (!email || !message) {
      setSubmitError('Please fill in all fields');
      return;
    }

    try {
      setIsSubmitting(true);
      await addDoc(collection(db, 'messages'), {
        email,
        message,
        wordCount,
        timestamp: serverTimestamp()
      });
      setEmail('');
      setMessage('');
      setSubmitSuccess(true);
      setTimeout(() => setSubmitSuccess(false), 4000);
    } catch (error) {
      console.error('Error submitting message:', error);
      setSubmitError('Failed to send message. Please try again.');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleMessageChange = (e) => {
    const input = e.target.value;
    const words = input.trim().split(/\s+/);

    if (words.length <= WORD_LIMIT) {
      setMessage(input);
    } else {
      const limitedMessage = words.slice(0, WORD_LIMIT).join(' ');
      setMessage(limitedMessage);
    }
  };

  const currentTestimonial = testimonials[currentTestimonialIndex];

  return (
    <motion.section
      className="contact-section"
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.8 }}
    >
      <div className="contact-container">
        {/* LEFT COLUMN - Contact Form */}
        <div className="contact-column contact-left">
          <motion.div
            initial={{ opacity: 0, x: -40 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.8, delay: 0.2 }}
          >
            <h2 className="section-title" style={{color:"white"}}>Get in Touch</h2>

            <div className="contact-info">
              <p className="linkedin-link">
                Connect on LinkedIn:{" "}
                <a
                  href="https://linkedin.com/in/rajat-amate"
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  linkedin.com/in/rajat-amate
                </a>
              </p>
            </div>

            <form onSubmit={handleSubmit} className="contact-form">
              <div className="form-group">
                <label htmlFor="email">Email</label>
                <input
                  type="email"
                  id="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="your@email.com"
                  required
                  disabled={isSubmitting}
                />
              </div>

              <div className="form-group">
                <label htmlFor="message">
                  Message ({wordCount}/{WORD_LIMIT} words)
                </label>
                <textarea
                  id="message"
                  value={message}
                  onChange={handleMessageChange}
                  placeholder="Share your thoughts or inquiries..."
                  required
                  disabled={isSubmitting}
                />
              </div>

              <AnimatePresence mode="wait">
                {submitError && (
                  <motion.div
                    key="error"
                    className="error-message"
                    initial={{ opacity: 0, y: -10 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: -10 }}
                  >
                    {submitError}
                  </motion.div>
                )}
                {submitSuccess && (
                  <motion.div
                    key="success"
                    className="success-message"
                    initial={{ opacity: 0, y: -10 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: -10 }}
                  >
                    ✓ Message sent successfully!
                  </motion.div>
                )}
              </AnimatePresence>

              <motion.button
                type="submit"
                className="submit-btn"
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                disabled={isSubmitting}
              >
                {isSubmitting ? 'Sending...' : 'Send Message'}
              </motion.button>
            </form>
          </motion.div>
        </div>

        {/* RIGHT COLUMN - Testimonials Carousel */}
        <div className="contact-column contact-right">
          <motion.div
            initial={{ opacity: 0, x: 40 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.8, delay: 0.4 }}
          >
            <h2 className="testimonials-title" style={{color:"white"}}>Testimonials</h2>

            <div className="testimonials-carousel">
              <AnimatePresence mode="wait">
                <motion.div
                  key={currentTestimonialIndex}
                  className="testimonial-card"
                  initial={{ opacity: 0, x: 100 }}
                  animate={{ opacity: 1, x: 0 }}
                  exit={{ opacity: 0, x: -100 }}
                  transition={{ duration: 0.5 }}
                >
                  
                  <p className="testimonial-text">"{currentTestimonial.quote}"</p>

                  <div className="testimonial-author">
                    <div className="author-info">
                      <p className="author-name">{currentTestimonial.author}</p>
                      <p className="author-role">{currentTestimonial.role}</p>
                      <p className="author-institution">
                        {currentTestimonial.institution}
                      </p>
                    </div>
                  </div>
                </motion.div>
              </AnimatePresence>

              
            </div>
          </motion.div>
        </div>
      </div>
    </motion.section>
  );
};

export default Contact;
