
import React, { useRef } from 'react';
import 'bootstrap/dist/css/bootstrap.min.css';
import PrismaticBurst from './PrismaticBurst';
import ShinyText from './ShinyText';
import TypingAnimation from './TypingAnimation';
import './Hello3D.css';

const Hello3D = () => {
  const heroRef = useRef(null);

  const roles = [
    'Software Engineer',
    'AI Engineer',
    'Data Analyst',
    'Business Analyst',
    'Enthusiastic Learner'
  ];

  const navigateToGitHub = () => {
    window.open('https://github.com/Imercenary27', '_blank');
  };

  const scrollToNext = () => {
    const nextSection = document.getElementById('aboutme');
    if (nextSection) {
      nextSection.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <div className="main-container">
      <header className="hero-header prismatic-hero" ref={heroRef}>
        <div className="prismatic-wrapper">
          <PrismaticBurst
            intensity={2}
            speed={0.5}
            animationType="rotate3d"
            distort={1.0}
            paused={false}
            offset={{ x: 0, y: 0 }}
            hoverDampness={0.25}
            rayCount={24}
            mixBlendMode="lighten"
            colors={['#ff007a', '#4d3dff', '#ffffff']}
          />
        </div>

        <div className="hero-content">
          <h1 className="welcome-text" style={{ fontSize: '4rem' }}>
            <ShinyText text="Welcome to My Portfolio" disabled={false} speed={3} />
          </h1>
          <p>
            Hi, I am Rajat Amate, a <TypingAnimation roles={roles} speed={80} pauseDuration={2000} />
          </p>
          <p className="subtitle-text">
            passionate about solving real-world problems with innovative solutions.
          </p>
          <div className="button-group">
            <button className="cta-button" onClick={navigateToGitHub}>
              Learn More
            </button>
            <button className="cta-button get-started" onClick={scrollToNext}>
              Get Started
            </button>
          </div>
        </div>
      </header>

      {/* Your next section elsewhere in the JSX should have id="aboutme" */}
    </div>
  );
};

export default Hello3D;