// Gallery.js
import React, { useState, useEffect } from 'react';
import './Gallery.css';

// Utility function to import local images from folder
const importLocalImages = () => {
  const imageContext = require.context('../myimages', false, /\.(jpg|jpeg|png|gif)$/i);
  return imageContext.keys().map((key, idx) => ({
    id: idx,
    src: imageContext(key),
    alt: key.replace('./', '').split('.')[0]
  }));
};

const InfiniteScrollGallery = () => {
  const [images, setImages] = useState([]);
  const [row1Images, setRow1Images] = useState([]);
  const [row2Images, setRow2Images] = useState([]);

  useEffect(() => {
    try {
      const loadedImages = importLocalImages();
      setImages(loadedImages);

      // Split images into two groups for different rows
      const mid = Math.ceil(loadedImages.length / 2);
      const group1 = loadedImages.slice(0, mid);
      const group2 = loadedImages.slice(mid);

      // If we have odd number of images, duplicate the last one for group2
      if (group2.length === 0) {
        group2.push(...group1);
      }

      // Create infinite ribbon by tripling for seamless loop
      const tripled1 = [...group1, ...group1, ...group1];
      const tripled2 = [...group2, ...group2, ...group2];

      setRow1Images(tripled1);
      setRow2Images(tripled2);
    } catch (error) {
      console.warn('Could not load images from /myimages folder. Using placeholder images.');
      
      // Create placeholder images split into two groups
      const placeholderImages = Array.from({ length: 12 }, (_, i) => ({
        id: i,
        src: `https://picsum.photos/${300}/${280}?random=${i}`,
        alt: `Gallery item ${i + 1}`
      }));

      const mid = 6;
      const group1 = placeholderImages.slice(0, mid);
      const group2 = placeholderImages.slice(mid);

      setImages(placeholderImages);
      const tripled1 = [...group1, ...group1, ...group1];
      const tripled2 = [...group2, ...group2, ...group2];

      setRow1Images(tripled1);
      setRow2Images(tripled2);
    }
  }, []);

  return (
    <section className="gallery-section">
      <div className="gallery-header">
        <h2>Catch A Glimpse</h2>
      </div>

      <div className="gallery-wrapper">
        {/* Row 1 - Scrolling Left */}
        <div className="gallery-row">
          <div className="gallery-track gallery-track-1">
            {row1Images.map((image, idx) => (
              <div key={`row1-${idx}`} className="gallery-item">
                <img
                  src={image.src}
                  alt={image.alt}
                  loading="lazy"
                />
              </div>
            ))}
            {/* Duplicate for seamless loop */}
            {row1Images.map((image, idx) => (
              <div key={`row1-dup-${idx}`} className="gallery-item">
                <img
                  src={image.src}
                  alt={image.alt}
                  loading="lazy"
                />
              </div>
            ))}
          </div>
        </div>

        {/* Row 2 - Scrolling Right */}
        <div className="gallery-row">
          <div className="gallery-track gallery-track-2">
            {row2Images.map((image, idx) => (
              <div key={`row2-${idx}`} className="gallery-item">
                <img
                  src={image.src}
                  alt={image.alt}
                  loading="lazy"
                />
              </div>
            ))}
            {/* Duplicate for seamless loop */}
            {row2Images.map((image, idx) => (
              <div key={`row2-dup-${idx}`} className="gallery-item">
                <img
                  src={image.src}
                  alt={image.alt}
                  loading="lazy"
                />
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
};

const Gallery = () => {
  return (
    <>
      <InfiniteScrollGallery />
    </>
  );
};

export default Gallery;
