import React, { useState } from 'react';
import { SocialIcon } from 'react-social-icons';
import * as pdfjsLib from 'pdfjs-dist';
import './Footer.css';

// Set up the worker
pdfjsLib.GlobalWorkerOptions.workerSrc = `//cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjsLib.version}/pdf.worker.min.js`;

const PDFViewer = ({ pdfPath, onClose }) => {
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(0);
  const [loading, setLoading] = useState(true);
  const [scale, setScale] = useState(1);

  React.useEffect(() => {
    const loadPDF = async () => {
      try {
        const pdf = await pdfjsLib.getDocument(pdfPath).promise;
        setTotalPages(pdf.numPages);
        setLoading(false);
      } catch (error) {
        console.error('Error loading PDF:', error);
        setLoading(false);
      }
    };

    loadPDF();
  }, [pdfPath]);

  const handlePrevPage = () => {
    if (currentPage > 1) setCurrentPage(currentPage - 1);
  };

  const handleNextPage = () => {
    if (currentPage < totalPages) setCurrentPage(currentPage + 1);
  };

  const handleZoom = (direction) => {
    if (direction === 'in' && scale < 2) setScale(scale + 0.1);
    if (direction === 'out' && scale > 0.5) setScale(scale - 0.1);
  };

  return (
    <div className="cv-modal-overlay" onClick={onClose}>
      <div className="cv-modal-content" onClick={(e) => e.stopPropagation()}>
        <button className="cv-modal-close" onClick={onClose}>
          ✕
        </button>

        {/* PDF Toolbar */}
        <div className="cv-toolbar">
          <div className="cv-toolbar-left">
            <button 
              className="cv-btn-icon" 
              onClick={handlePrevPage}
              disabled={currentPage === 1}
              title="Previous page"
            >
              ← Previous
            </button>
            <span className="cv-page-info">
              Page {currentPage} of {totalPages}
            </span>
            <button 
              className="cv-btn-icon" 
              onClick={handleNextPage}
              disabled={currentPage === totalPages}
              title="Next page"
            >
              Next →
            </button>
          </div>

          <div className="cv-toolbar-right">
            <button 
              className="cv-btn-icon" 
              onClick={() => handleZoom('out')}
              disabled={scale <= 0.5}
              title="Zoom out"
            >
              −
            </button>
            <span className="cv-zoom-level">{Math.round(scale * 100)}%</span>
            <button 
              className="cv-btn-icon" 
              onClick={() => handleZoom('in')}
              disabled={scale >= 2}
              title="Zoom in"
            >
              +
            </button>
          </div>
        </div>

        {/* PDF Preview */}
        <div className="cv-preview">
          {loading && <div className="cv-loading">Loading PDF...</div>}
          {!loading && (
            <PDFPage 
              pdfPath={pdfPath} 
              pageNum={currentPage} 
              scale={scale}
            />
          )}
        </div>

        {/* Action Buttons */}
        <div className="cv-modal-actions">
          <a 
            href="/RajatAmateGResume.pdf" 
            download="Rajat_Amate_Resume.pdf" 
            className="btn btn--primary"
          >
            ⬇ Download CV
          </a>
          <a 
            href="/RajatAmateGResume.pdf" 
            target="_blank" 
            rel="noopener noreferrer" 
            className="btn btn--outline"
          >
            🔗 Open in New Tab
          </a>
        </div>
      </div>
    </div>
  );
};

const PDFPage = ({ pdfPath, pageNum, scale }) => {
  const canvasRef = React.useRef(null);

  React.useEffect(() => {
    const renderPage = async () => {
      try {
        const pdf = await pdfjsLib.getDocument(pdfPath).promise;
        const page = await pdf.getPage(pageNum);
        const viewport = page.getViewport({ scale });
        const canvas = canvasRef.current;
        const context = canvas.getContext('2d');

        canvas.width = viewport.width;
        canvas.height = viewport.height;

        await page.render({ canvasContext: context, viewport }).promise;
      } catch (error) {
        console.error('Error rendering page:', error);
      }
    };

    renderPage();
  }, [pdfPath, pageNum, scale]);

  return <canvas ref={canvasRef} className="cv-canvas" />;
};

const Footer = () => {
  const [showCVModal, setShowCVModal] = useState(false);
  const currentYear = new Date().getFullYear();

  const footerSections = {
    quickLinks: [
      { label: 'Home', href: '#home' },
      { label: 'About Me', href: '#aboutme' },
      { label: 'Experience', href: '#experience' },
      { label: 'Certifications', href: '#certifications' },
      { label: 'Projects', href: '#projects' },
      { label: 'Contact', href: '#contact' }
    ],
    resources: [
      { label: 'Resume/CV', href: '#', onClick: (e) => { e.preventDefault(); setShowCVModal(true); } },
      { label: 'Blog', href: 'https://medium.com/@amaterajat67' },
      { label: 'Resources', href: '#resources' }
    ],
    legal: []
  };

  return (
    <>
      <footer className="footer">
        <div className="footer-container">
          {/* Social Links */}
          <div className="footer-top">
            <div className="social-container">
              <SocialIcon url="https://x.com/imercenary27" network="twitter" className="social-icon" />
              <SocialIcon url="https://linkedin.com/in/rajat-amate" network="linkedin" className="social-icon" />
              <SocialIcon url="https://github.com/Imercenary27" network="github" className="social-icon" />
              <SocialIcon url="https://instagram.com/imercenaryy" network="instagram" className="social-icon" />
            </div>
          </div>

          {/* Middle Section */}
          <div className="footer-middle">
            <div className="footer-column">
              <h4 className="footer-heading">Quick Links</h4>
              <ul className="footer-links">
                {footerSections.quickLinks.map((link, index) => (
                  <li key={index}>
                    <a href={link.href} className="footer-link">
                      {link.label}
                    </a>
                  </li>
                ))}
              </ul>
            </div>

            <div className="footer-column">
              <h4 className="footer-heading">Resources</h4>
              <ul className="footer-links">
                {footerSections.resources.map((link, index) => (
                  <li key={index}>
                    <a 
                      href={link.href} 
                      className="footer-link"
                      onClick={link.onClick}
                    >
                      {link.label}
                    </a>
                  </li>
                ))}
              </ul>
            </div>

            <div className="footer-column">
              <h4 className="footer-heading">Get In Touch</h4>
              <div className="footer-contact">
                <p>
                  <a href="mailto:amaterajat67@gmail.com" className="footer-link">
                    amaterajat67@gmail.com
                  </a>
                </p>
                <p className="footer-location">📍 Dublin, Ireland</p>
              </div>
            </div>
          </div>

          {/* Bottom Section */}
          <div className="footer-bottom">
            <div className="footer-copyright">
              <p>
                © {currentYear} <strong>Rajat Amate</strong>. All Rights Reserved.
              </p>
            </div>
            <p className="footer-tagline">
              Crafting solutions with <span className="heart">❤️</span> and code
            </p>
          </div>
        </div>
      </footer>

      {/* CV Modal with PDF Viewer */}
      {showCVModal && (
        <PDFViewer 
          pdfPath="/RajatAmateGResume.pdf" 
          onClose={() => setShowCVModal(false)}
        />
      )}
    </>
  );
};

export default Footer;
