// Pages/Loader.js
import { useProgress } from '@react-three/drei';
import { PuffLoader } from 'react-spinners';
// import loadingSvg from  "../images/loadingname.svg"; 
// import loadingmp4 from "../images/loading.mp4";
import loadingmp from "../images/loading2.mp4"
import './Loader.css';

// Fullscreen loader without R3F hooks
export const FullScreenLoader = () => (
  <div className="fullscreen-loader">
    <div className="lottie-loader">
      {/* <PuffLoader color="#4a90e2" size={80} /> */}
      {/* <img 
        src={loadingmp4} 
        alt="Loading" 
        className="loading-svg" 
      /> */}
      <video
        src={loadingmp}
        className="loading-video"
        autoPlay
        loop
        muted
        playsInline
        width={320} // adjust as needed
        height={320} // adjust as needed
        // style={{ margin: '16px 0' }}
        style={{ margin: '64px 0' }}
      />

      <h2 className="loading-text">Initializing Portfolio</h2>
    </div>
  </div>
);

// Three.js specific loader (use inside Canvas)
export const ThreeLoader = () => {
  const { progress } = useProgress();
  return (
    <div className="three-loader">
      <PuffLoader color="#4a90e2" size={80} />
      <p className="progress-text">{Math.round(progress)}% loaded</p>
    </div>
  );
};

export default FullScreenLoader;
