// src/components/AboutMe.js
import React from 'react';
import DecryptedText from './DecryptedText';
import ProfileCard from './ProfileCard';
import profileImage from '../images/profileimage.png';
import logoImage from '../images/logorajat.svg';
import './AboutMe.css';

const AboutMe = () => {
  return (
    <section className="about-section">
      <div className="about-container">
        <div className="about-content">
          <h1 className="about-title">
            <DecryptedText
              text="Hey You!!"
              animateOn="view"
              speed={75}
              maxIterations={15}
              className="revealed"
            />
          </h1>
          
          <div className="about-text">
            <p>
              <DecryptedText
                text="Welcome to my digital playground! I'm Rajat, a caffeine-powered AI enthusiast who accidentally turned debugging into an art form. 🎨"
                animateOn="view"
                speed={30}
                sequential={true}
                revealDirection="start"
              />
            </p>
            
            <p>
              <DecryptedText
                text="Currently based in Dublin (yes, the one with leprechauns and excellent tech scene), I spend my days teaching machines to be smarter while trying not to create Skynet. So far, so good! 🤖"
                animateOn="view"
                speed={35}
                sequential={true}
              />
            </p>
            
            <p>
              <DecryptedText
                text="When I'm not wrestling with neural networks or explaining to my models why they can't just 'figure it out', you'll find me writing about AI on Medium, pretending to understand maritime navigation systems, or optimizing something that probably didn't need optimizing."
                animateOn="view"
                speed={25}
                sequential={true}
              />
            </p>
            
            <p>
              <DecryptedText
                text="I believe in clean code, messy whiteboards, and the magical power of turning coffee into algorithms. My superpower? Making complex AI concepts sound like they make sense (results may vary). ☕"
                animateOn="view"
                speed={40}
                sequential={true}
              />
            </p>
            
            <p>
              <DecryptedText
                text="Fun fact: I've participated in more hackathons than I've had hot dinners, and my GitHub contributions graph looks like a very confused heartbeat monitor. But hey, at least the commits are consistent! 📈"
                animateOn="view"
                speed={30}
                sequential={true}
              />
            </p>
            
            <div className="about-cta">
              <DecryptedText
                text="Stick around, explore my projects, read my occasionally coherent thoughts on Medium, or just enjoy watching the pixel animations dance. Either way, thanks for stopping by my corner of the internet! 🚀"
                animateOn="view"
                speed={25}
                sequential={true}
                className="cta-text"
              />
            </div>
          </div>
        </div>

        <div className="about-profile" style={{width:"fit-content"}}>
          <ProfileCard
            name="Rajat Amate"
            title="Technology Enthusiast"
            handle="Rajat Amate"
            status="Glad to meet you!"
            
            avatarUrl={profileImage}
            iconUrl={logoImage}
            showUserInfo={true}
            enableTilt={true}
            enableMobileTilt={false}
            onContactClick={() => {
              // Scroll to contact section or open LinkedIn
              window.open('https://linkedin.com/in/rajat-amate', '_blank');
            }}
          />
        </div>
      </div>
    </section>
  );
};

export default AboutMe;
